"""50 individually authored administration, procurement and justice reviews."""
exec(compile(open('scripts/review/cp-reviewed-overlay.py').read(),'cp-reviewed-overlay.py','exec'))
add(317,'Servidor solicita vantagem indevida em razão da função, embora não pratique o ato pretendido.','Corrupção privilegiada por influência de pedido tem requisitos e pena próprios, não pressupõe pagamento.','Solicitar exige recebimento efetivo para consumar essa modalidade? Não.','Qualquer presente sem vínculo funcional prova o crime? Não; demonstrar elementos.')
add(318,'Funcionário facilita contrabando infringindo dever funcional.','Particular que importa mercadoria proibida exige distinguir334-A e participação, sem presumir qualidade funcional.','Facilitar descaminho também está previsto? Sim.','Contrabando atual está todo no334? Não;334-A tem tipo próprio.')
add(319,'Servidor retarda indevidamente ato de ofício para satisfazer vingança pessoal.','Atraso por impossibilidade real ou mera negligência não prova o interesse/sentimento típico.','Motivo pessoal importa? Sim.','Qualquer demora é prevaricação automática? Não.')
add('319-a','Agente público com dever de vedação deixa de impedir acesso do preso a aparelho comunicador.','O preso não é sujeito funcional desse tipo apenas porque usa telefone; outros regimes precisam ser separados.','Só celular entra? Não; rádio e similar comunicador também.','Qualquer trabalhador sem o dever indicado responde automaticamente? Não.')
add(320,'Superior deixa de responsabilizar subordinado por indulgência.','Se não tem competência, omitir comunicação à autoridade competente também integra a alternativa legal.','Indulgência importa? Sim.','Falta de competência autoriza sempre silêncio? Não.')
add(321,'Funcionário patrocina interesse privado perante a Administração valendo-se do cargo.','Interesse legítimo não exclui caput por si; ilegitimidade tem modalidade própria.','Precisa ser advogado inscrito? Não.','É todo auxílio particular sem uso do cargo? Não.')
add(322,'Conduta de violência funcional exige comparar texto residual com tipos atuais de abuso de autoridade.','Não ensinar pena residual como enquadramento universal nem declarar revogação incontroversa de toda situação.','A leitura do caput resolve sozinha o regime atual? Não.','Toda atuação policial com força é automaticamente criminosa? Não; requisitos,legalidade e legislação específica importam.')
add(323,'Funcionário abandona cargo fora das hipóteses legais.','Ausência justificada ou exercício lícito de direito não é abandono por presunção.','Faixa de fronteira tem modalidade agravada? Sim.','Todo atraso equivale a abandonar cargo? Não.')
add(324,'Agente continua a função sabendo que foi suspenso por ato válido.','Sem ciência do ato ou sem efeito válido, o pressuposto precisa ser examinado.','Iniciar antes das exigências legais também está previsto? Sim.','Toda demora administrativa em registrar ato prova crime? Não.')
add(325,'Servidor entrega credencial para acesso indevido a sistema sigiloso.','Transparência legalmente exigida não se confunde com revelar fato que deva permanecer secreto.','Facilitar acesso não autorizado está previsto? Sim.','Qualquer informação administrativa é sigilosa por presunção? Não.')
add(326,'Questão sobre sigilo de proposta exige integrar337-J e transição penal das licitações.','Pena antiga de326 não deve ser automaticamente apresentada como pena atual de todo certame.','O texto residual basta ao enquadramento atual? Não.','Lei14.133 só mudou procedimentos administrativos? Não; também tipos penais.')
add(327,'Pessoa exerce função pública temporária sem remuneração.','Isso pode preencher conceito penal, mas não dispensa provar conduta e elementos do crime imputado.','Salário é indispensável ao conceito? Não.','Todo empregado privado é funcionário público por presunção? Não; equiparação tem requisitos.')
add(328,'Agente pratica ato reservado a função pública que não lhe compete.','Inclusive servidor pode usurpar outra função; não limitar automaticamente a particular.','Vantagem obtida tem pena própria? Sim.','Só anunciar-se servidor sem usurpar ato equivale sempre a328? Não.')
add(329,'Violência é usada para impedir execução de ato legal por funcionário competente.','Discordância verbal ou resistência a ato ilegal não satisfaz automaticamente esse tipo.','Legalidade do ato importa? Sim.','Violência pode ter pena cumulativa própria? Sim.')
add(330,'Destinatário descumpre conscientemente ordem legal de funcionário competente.','Sanção administrativa especial ou tipo específico exigem examinar subsidiariedade, não duplicar imputação automaticamente.','Toda ordem informal é legal por presunção? Não.','Descumprir medida protetiva tem sempre só330? Não; há tipos próprios.')
add(331,'Ofensa típica é dirigida a funcionário no exercício ou em razão da função.','Crítica à atuação pública não se converte automaticamente em desacato; contexto e requisitos precisam ser provados.','Vínculo com a função importa? Sim.','Toda reclamação áspera basta por si? Não.')
add(332,'Agente cobra vantagem a pretexto de influir em ato de funcionário.','Se afirma destinar também ao funcionário, examinar parágrafo; corrupção real tem outros elementos.','É preciso demonstrar efetivo êxito da influência? Não; tipo trata de solicitar,exigir,cobrar ou obter no recorte.','Aumento é metade? Sim; hipótese legal.')
add(333,'Particular oferece vantagem indevida para funcionário omitir ato de ofício.','Recusa da oferta não torna automaticamente atípica a modalidade consumada de oferecer.','Só prometer também está previsto? Sim.','Todo pagamento sem oferta/promessa típica prova333? Não; enquadramento e conduta precisam ser identificados.')
add(334,'Importador ilude tributo devido sobre mercadoria de entrada permitida.','Mercadoria proibida ou hipótese equiparada de contrabando exige334-A, não confundir tributo com proibição.','Descaminho tem pena de1 a4? Sim; caput.','Irregularidade fiscal sozinha dispensa dolo e critérios de tipicidade? Não.')
add('334-a','Mercadoria proibida é importada nas condições típicas.','Hipótese de autorização/registro necessário pode integrar equiparação; não reduzir todo artigo à proibição absoluta.','Contrabando caput tem2 a5? Sim.','Toda discussão sobre tributo é contrabando? Não; distinguir334.')
add(335,'Conduta em certame exige comparação com337-I/337-K e regime temporal da Lei14.133.','Hasta pública e texto residual precisam de análise específica; não declarar revogação universal nem usar pena antiga indiscriminadamente.','Pode ignorar os novos tipos nas licitações atuais? Não.','Certame e hasta pública são sempre idênticos para enquadramento? Não.')
add(336,'Selo público colocado para lacrar objeto é violado nas condições típicas.','Abertura regularmente autorizada não equivale automaticamente a violação criminosa.','Edital legalmente afixado também é objeto previsto? Sim.','Todo cartaz privado entra? Não.')
add(337,'Documento confiado a terceiro por função pública é inutilizado.','Se o autor é guardião funcional, distinguir314; posse,guarda e autoria precisam ser demonstradas.','Documento pode estar com particular prestando serviço público? Sim.','Mero extravio fortuito prova dolo? Não.')
add('337-a','Informação salarial é omitida e contribuição previdenciária é suprimida no recorte legal.','Erro sem dolo ou sem resultado típico não basta; confissão espontânea antes da fiscalização tem requisitos próprios.','A extinção do§1º menciona pagamento como168-A? Não; não copiar os textos.','R$1.510 é limite congelado para sempre? Não;§4º prevê reajuste.')
add('337-b','Vantagem é dada a funcionário público estrangeiro para influenciar transação comercial internacional.','Não copiar333 excluindo dar; ato e transação internacional precisam ser identificados.','Dar está expressamente previsto? Sim.','Qualquer presente internacional prova crime sem finalidade típica? Não.')
add('337-c','Agente cobra vantagem a pretexto de influir em ato de funcionário estrangeiro em transação internacional.','Vantagem também atribuída ao funcionário tem aumento próprio; corrupção efetiva exige distinguir337-B.','A finalidade internacional importa? Sim.','Pena caput é igual à de332? Não.')
add('337-d','Empregado de organismo público internacional exerce função incluída na equiparação.','Empresa privada estrangeira comum não entra por nacionalidade isolada.','Função temporária ou gratuita pode contar? Sim.','Conceito dispensa os demais elementos do crime? Não.')
add('337-e','Contratação direta é autorizada fora das hipóteses legais com elementos do tipo.','Dispensa/inexigibilidade válida não é crime pelo simples uso de contratação direta.','Pena atual é4 a8 e multa? Sim.','Todo vício administrativo implica condenação automática? Não.')
add('337-f','Ajuste frustra competição visando vantagem decorrente da adjudicação.','Impugnação regular de edital ou disputa legítima não constitui fraude por si.','Finalidade de vantagem importa? Sim.','É só infração sem finalidade específica? Não; verificar tipo e prova.')
add('337-g','Patrocínio de interesse privado dá causa a contrato cuja invalidação é decretada judicialmente.','A invalidação judicial é elemento expresso; não substituí-la por mera discordância administrativa.','Tipo menciona invalidação judicial? Sim.','Qualquer consulta privada sem esse encadeamento basta? Não.')
add('337-h','Modificação contratual vantajosa não autorizada é admitida durante execução.','Exceção legal motivada à ordem cronológica de pagamento precisa ser distinguida de preterição típica.','Prorrogação irregular está abrangida? Sim.','Qualquer pagamento fora da sequência é automaticamente crime? Não; conferir autorização legal e elementos.')
add('337-i','Fraude perturba realização de ato do procedimento licitatório.','Recurso administrativo regular não se torna crime por atrasar cronograma.','Fraudar é uma das condutas? Sim.','Todo atraso de certame prova dolo típico? Não.')
add('337-j','Conteúdo de proposta sigilosa é entregue a terceiro nas condições típicas atuais.','Proposta legalmente pública não satisfaz sigilo por presunção; comparar326 residual.','Pena atual é detenção2 a3 e multa? Sim.','Pode ensinar universalmente a faixa antiga de326? Não.')
add('337-k','Vantagem é oferecida para afastar licitante.','A lei equipara quem se abstém/desiste em razão da vantagem; tentativa de afastar está expressa.','Violência ou grave ameaça também são meios previstos? Sim.','Tentar afastar fica sempre fora do caput? Não.')
add('337-l','Mercadoria vencida é entregue como perfeita causando prejuízo à Administração.','Diferença contratual sem fraude e prejuízo comprovados não satisfaz automaticamente o tipo.','Serviço em quantidade diversa pode integrar incisoI? Sim.','Prejuízo é irrelevante? Não; é elemento expresso.')
add('337-m','Empresa declarada inidônea é admitida em licitação.','Celebrar contrato com ela tem pena distinta e mais alta; também alcança o próprio inidôneo.','Participar e contratar têm a mesma faixa? Não.','Toda restrição cadastral equivale a declaração de inidoneidade? Não; conferir regime e validade.')
add('337-n','Inscrição cadastral é injustamente bloqueada para interessado.','Recusa regular e motivada por requisito legal não equivale a impedimento indevido.','Cancelamento indevido também entra? Sim.','Toda negativa cadastral basta sem injustiça/indevido? Não.')
add('337-o','Projetista omite sondagem relevante e frustra seleção de proposta vantajosa nas condições legais.','Divergência técnica sem relevante dissonância e demais elementos não basta.','Fim de benefício próprio/alheio dobra a pena? Sim;§2º.','Só plantas arquitetônicas integram condição de contorno? Não; inclui outros levantamentos legais.')
add('337-p','Multa dos crimes do capítulo respeita metodologia do CP e piso vinculado ao contrato.','Não aplicar esse percentual como piso universal a todo crime do Código.','Piso é2%? Sim.','Contratação direta também é base expressa? Sim.')
add(338,'Estrangeiro reingressa após expulsão válida nos pressupostos penais.','Não confundir expulsão com deportação ou impedimento temporário; direito migratório atual e validade da medida importam.','Qualquer retorno de estrangeiro é338? Não.','Mera nacionalidade prova o elemento expulsão? Não.')
add('338-a','Decisão judicial de medida protetiva aplicável é conscientemente descumprida.','Maria da Penha e Henry Borel possuem tipos próprios; não copiar indistintamente penas ou regras de fiança.','Competência civil/criminal do juiz é indiferente no§1º? Sim.','Delegado concede fiança no flagrante deste tipo? Não; apenas autoridade judicial.')
add(339,'Procedimento é instaurado contra pessoa por imputação que o agente sabe falsa e ela inocente.','Comunicar fato inexistente sem imputação pessoal exige distinguir340.','Abrange infração ético-disciplinar e improbidade? Sim; redação atual.','Suspeita razoável de boa-fé equivale automaticamente a denunciação caluniosa? Não.')
add(340,'Autoridade é acionada por notícia de crime que o comunicante sabe inexistente.','Acusação de pessoa sabidamente inocente com instauração pertinente exige339.','Contravenção inexistente também está prevista? Sim.','Notícia equivocada de boa-fé basta? Não.')
add(341,'Pessoa se acusa perante autoridade de crime cometido por outra.','Direito ao silêncio não transforma falsa autoacusação em prova legítima.','Crime inteiramente inexistente também entra? Sim.','Tipo é autoacusação de qualquer infração administrativa? Não; crime no texto.')
add(344,'Testemunha é gravemente ameaçada para favorecer interesse em investigação policial.','Interesse processual pode ser de terceiro; reivindicação lícita sem violência/ameaça não basta.','Juízo arbitral está previsto? Sim.','Processo sexual tem aumento próprio? Sim;1/3 até metade.')
add(345,'Credor retoma bem pela força para satisfazer pretensão, sem permissão legal.','Exercício expressamente permitido por lei é ressalva; dívida legítima não autoriza toda autotutela.','Pretensão legítima exclui sempre o crime? Não.','Sem violência procede mediante queixa? Sim; parágrafo.')
add(346,'Proprietário destrói coisa sua que terceiro detém por determinação judicial.','Ser dono não elimina a condição de detenção legítima por terceiro; dano à coisa alheia tem outro tipo.','Convenção também fundamenta detenção prevista? Sim.','A coisa necessariamente pertence a terceiro? Não; é própria.')
add(347,'Lugar é artificialmente alterado para enganar perito em processo civil pendente.','Para produzir efeito em processo penal, a lei alcança também processo ainda não iniciado e dobra penas.','Finalidade de induzir erro importa? Sim.','Todo reparo legítimo do local é fraude? Não.')
add(348,'Agente auxilia autor de crime a escapar da ação da autoridade.','Auxílio ao proveito exige distinguir349; isenção familiar tem recorte e extensão interpretativa não certificada aqui.','Crime antecedente sem reclusão tem pena própria? Sim.','Isenção do348 aplica-se automaticamente ao favorecimento real? Não.')
add(349,'Auxílio torna seguro proveito criminoso fora de coautoria ou receptação.','Ajudar pessoa a fugir é outro recorte; participação previamente ajustada exige classificação própria.','Subsidiariedade é expressa? Sim.','A isenção familiar do348 vale automaticamente aqui? Não.')
patch(318,remissoes=['CP art.334 (descaminho)','CP art.334-A (contrabando)'],atencao=['Crime funcional de facilitação com infração do dever; distinguir particular,participação e tipos atuais334/334-A.'])
patch(318,simples='Facilitação de contrabando ou descaminho com infração de dever funcional: reclusão3 a8 e multa. A referência textual antiga a334 exige integração atual:334 é descaminho,334-A é contrabando.')
patch(317,atencao=['Solicitar ou aceitar promessa não exige recebimento efetivo para consumação dessas modalidades. Receber tem consumação própria. Relação com função e ato pertinente precisam ser examinados;§1º e corrupção privilegiada têm requisitos próprios, sem dizer que todo ato de ofício apenas aumenta pena.','Funcionário é sujeito próprio; concurso de particulares depende dos requisitos legais.'])
patch(327,pontos=['Cargo,emprego ou função pública mesmo temporária/gratuita.','Equiparação do§1º tem condições próprias, não abrange toda atividade privada.','§2º: terça parte para crimes deste Capítulo, com cargo/função e entidades expressamente indicados; não basta o título de chefia isolado.'])
patch(319,atencao=['Interesse/sentimento pessoal e dolo precisam ser demonstrados. Não importar conclusão universal de que todo atraso ou toda vantagem caracteriza automaticamente este ou outro tipo. Texto oficial remete à ADPF881; não certificada aqui toda controvérsia ou decisão posterior.'])
for n in [322,326,335]:note(n,'Texto residual/histórico exige confronto com legislação especial e regime temporal vigente. Sem exercício literal automático de pena antiga ou conclusão universal de revogação; não certificadas todas as controvérsias de especialidade/recepção.')
note(323,'Ausência justificada e direitos constitucionais, inclusive greve lícita, não podem ser criminalizados só pelo afastamento físico.')
patch(328,atencao=['Qualidade de particular não é exclusividade absoluta; servidor também pode usurpar função que não lhe compete. Distinguir efetiva usurpação de mera identificação/apresentação.'])
note(330,'Ordem legal e competência precisam de prova. Regime com sanção própria e ausência/presença de ressalva penal exigem análise, sem duplicação automática.')
note(331,'Crítica,petição e liberdade de expressão não são desacato por presunção. Não declarar descriminalização universal; não certificada toda jurisprudência posterior ou recepção de cada situação.')
for n in [334,'334-a']:note(n,'Majorantes,insignificância,modalidade de transporte e reiteração exigem fatos e jurisprudência pertinentes. Não certificado limite monetário/agravamento universal neste lote; nenhuma resposta automática por valor ou meio de transporte.')
note('337-a','LC225 publicada em9/1/2026 introduz§§5º/6º para contumaz: não generalizar extinção. Regimes de pagamento/parcelamento dependem também de Lei10.684 art.9 vigente; parcelamento não é pagamento integral. Valor histórico do§3º precisa de reajuste do§4º; não certificado limite nominal atual.')
patch('337-a',pontos=['Supressão/redução previdenciária com conduta e dolo típicos;2 a5 anos e multa.','§1º exige declaração,confissão e informações espontâneas antes da ação fiscal; confrontar§§5º/6º do contumaz.','§2º depende de primariedade,bons antecedentes e hipóteses legais; faculdade,não extinção automática.','§§3º/4º: limite histórico sujeito a reajuste,sem certificação de valor atual.'])
for key in ['337-e','337-f','337-g','337-h','337-i','337-j','337-k','337-l','337-m','337-n','337-o','337-p']:note(key,'Lei14.133/2021 inseriu tipos penais; distinguir entrada em vigor penal da transição administrativa dos regimes de contratação. Não retroagir pena mais grave; irregularidade administrativa não prova automaticamente dolo e demais elementos.')
note('337-h','Art.141 da Lei14.133 contém hipóteses legais motivadas de alteração da ordem cronológica; não ensinar que qualquer pagamento fora da sequência é crime.')
patch('337-h',atencao=['Modificação/prorrogação sem autorização e preterição típica de pagamento têm requisitos próprios. Irregularidade administrativa não prova automaticamente dolo.','Lei14.133 art.141 prevê exceções legais motivadas à ordem cronológica; não dizer que todo pagamento fora da sequência é crime.','Distinguir transição administrativa e entrada em vigor penal; sem retroatividade gravosa.'])
note(338,'Expulsão,deportação e impedimento não se confundem. Confrontar Lei de Migração e validade/efeitos da medida; não presumir crime por nacionalidade.')
note('338-a','Incluído por Lei15.280 publicada/vigente em8/12/2025. Verificar âmbito da medida e especialidade de tipos próprios de outras leis; não copiar automaticamente regras da Maria da Penha ou Henry Borel.')
patch(344,atencao=['Processos judicial,policial,administrativo e arbitragem estão no texto. Não exigir ação judicial já ajuizada para toda hipótese; violência/ameaça,finalidade e contexto precisam de prova.'])
patch(348,atencao=['Pena depende do crime antecedente. Rol textual de isenção: ascendente,descendente,cônjuge,irmão. Extensão a companheiro envolve interpretação; não certificada conclusão restritiva universal nem extensão automática a todo familiar ou ao349.'])
